fn owned_markers(host: &SimHost) -> Vec<(CellPos, Marker, sim::PlayerId)> {
    let Some(players) = host.players() else {
        return Vec::new();
    };
    let mut markers = Vec::new();
    if let Some(mut units) = host.world().try_query::<(&sim::SimId, &Owner, &Mobile)>() {
        for (id, owner, mobile) in units.iter(host.world()) {
            if crate::units::unit_shown(owner.0, mobile, players)
                && !host
                    .world()
                    .get_resource::<sim::SpecialState>()
                    .is_some_and(|s| s.hidden.contains(&(HUMAN, *id)))
            {
                let marker = if owner.0 == HUMAN {
                    Marker::OwnUnit
                } else {
                    Marker::EnemyUnit
                };
                markers.push((mobile.cell, marker, owner.0));
            }
        }
    }
    if let Some(mut buildings) = host.world().try_query::<(&Owner, &Building)>() {
        for (owner, building) in buildings.iter(host.world()) {
            if crate::buildings::building_shown(owner.0, building.footprint, players) {
                let marker = if owner.0 == HUMAN {
                    Marker::OwnBuilding
                } else {
                    Marker::EnemyBuilding
                };
                markers.extend(
                    building
                        .footprint
                        .cells()
                        .map(|cell| (cell, marker, owner.0)),
                );
            }
        }
    }
    // Units are drawn over buildings (a unit never stands in a building's cell, I6).
    markers.sort_by_key(|(_, marker, _)| matches!(marker, Marker::OwnUnit | Marker::EnemyUnit));
    markers
}

fn draw_minimap(
    teams: Option<Res<crate::presentation::TeamColors>>,
    notices: Option<Res<PublicBuildingNotices>>,
    host: Res<SimHost>,
    terrain: Option<Res<MapTerrain>>,
    looks: Option<Res<crate::map::MapLooks>>,
    minimap: Option<Res<Minimap>>,
    mut state: ResMut<MinimapState>,
    mut images: ResMut<Assets<Image>>,
) {
    let (Some(terrain), Some(minimap)) = (terrain, minimap) else {
        return;
    };
    let tick = host.tick();
    let notice_revision = notices.as_deref().map_or(0, |notices| notices.revision);
    if state.drawn_tick == Some(tick) && state.notice_revision == notice_revision {
        return;
    }
    // Without radar nothing of the map is drawn (RA2).
    let online = radar_online(&host);
    let pixels = if online {
        let owned = owned_markers(&host);
        let marked: Vec<_> = owned
            .iter()
            .map(|&(cell, marker, _)| (cell, marker))
            .collect();
        let mut colours = cell_colours_with_looks(
            &terrain.0,
            looks.as_deref().map_or(&[], |l| l.0.as_slice()),
            human_vision(host.players()),
            &marked,
        );
        for &(cell, _, owner) in &owned {
            let rgb = teams
                .as_deref()
                .unwrap_or(&crate::presentation::TeamColors(0))
                .rgb_of(owner);
            if let Some(pixel) =
                colours.get_mut((cell.y as u32 * terrain.0.width() + cell.x as u32) as usize)
            {
                *pixel = [rgb[0], rgb[1], rgb[2], 255];
            }
        }
        let mut pixels = render(&minimap.layout, &colours);
        if let Some(notices) = notices.as_deref() {
            draw_public_building_notices(&minimap.layout, notices, &owned, &mut pixels);
        }
        pixels
    } else {
        offline_pixels(&minimap.layout)
    };
    state.offline = !online;
    state.lit_pixels = pixels
        .as_chunks::<4>()
        .0
        .iter()
        .filter(|pixel| pixel[3] > 0 && pixel[..3] != [0, 0, 0])
        .count();
    state.map_pixels = map_pixels(&pixels);
    if let Some(mut image) = images.get_mut(&minimap.image)
        && image.data.as_ref() != Some(&pixels)
    {
        image.data = Some(pixels);
    }
    state.notice_revision = notice_revision;
    state.drawn_tick = Some(tick);
    state.drawings = state.drawings.saturating_add(1);
}

fn unit_shown(owner: PlayerId, mobile: &Mobile, players: &Players) -> bool {
    owner == HUMAN
        || players
            .get(HUMAN)
            .is_some_and(|state| state.vision().sees_unit(mobile))
}

fn building_shown(owner: PlayerId, footprint: Footprint, players: &Players) -> bool {
    owner == HUMAN
        || players
            .get(HUMAN)
            .is_some_and(|state| state.vision().sees_footprint(footprint))
}

lobby4.match_rules_body:
pub struct MatchRules {
    /// A player is defeated without buildings and base unit; off: without buildings and units.
    /// Read only in a world with a rules file.
    pub short_game: bool,
    /// Superweapon buildings may be queued.
    pub superweapons: bool,
    /// `Command::Undeploy` is accepted.
    pub mcv_repacks: bool,
    /// Crates appear (RA5, `crate::crates`): in a match with players, in a world with a rules
    /// file.
    pub crates: bool,
    /// Ore grows and spreads (RA5, `crate::ore`; the lobby's `TiberiumGrows`). Read only in a
    /// world with a rules file.
    pub ore_grows: bool,
    pub bridge_destruction: bool,
    /// Explored cells cease showing current activity when enabled (RA7).
    pub fog_of_war: bool,
}

lobby4.match_options_body:
pub struct MatchOptions {
    /// Human controllers with Super Me.
    pub super_players: Vec<PlayerId>,
    /// Human controllers whose building prerequisites are waived.
    pub unlock_players: Vec<PlayerId>,
    /// The speed of the units of the Super Me players in percent of their type's speed, from
    /// 100 to [`MAX_UNIT_SPEED_PERCENT`] (values outside are clamped; 0 means 100). Players
    /// without Super Me are never changed.
    pub unit_speed_percent: u16,
    /// Off (the default, fixed decision 3): in a match with a human player, the computer players
    /// form one team: they do not fire at each other, do not march on each other's bases, and
    /// the match ends once only they are left; without a human player nothing changes. On:
    /// every player for itself.
    pub free_for_all: bool,
    /// Players whose faction is drawn from the countries of the skirmish file with `SimRng`
    /// (the lobby's "random"), in ascending order of their ids; their `PlayerSetup::faction` is
    /// not read.
    pub random_countries: Vec<PlayerId>,
    /// The starting credits of every player; `None` for those of the skirmish file. With a
    /// rules file they must lie in its range and on its step (`MinMoney`, `MaxMoney`,
    /// `MoneyIncrement`).
    pub starting_credits: Option<i64>,
    /// The lobby's unit count, from which the starting units of a country's players follow
    /// ([`starting_units`]); `None` for the default of the rules file. It must lie in the
    /// range of the rules file.
    pub unit_count: Option<u32>,
    /// A country's player starts with the base unit of its side; off: with the Construction
    /// Yard it deploys into, standing at the start position.
    pub mcv_start: bool,
    /// See [`MatchRules`].
    pub short_game: bool,
    pub superweapons: bool,
    pub crates: bool,
    pub mcv_repacks: bool,
    pub ore_grows: bool,
    pub bridge_destruction: bool,
    /// Explored cells cease showing current activity when enabled (RA7).
    pub fog_of_war: bool,
}
